mapper.update:
UPDATE tb_storage_provider_config
SET last_validation_status = #{status},
    last_validation_at = #{validatedAt},
    last_validation_message = #{message}
WHERE id = #{id}

UPDATE tb_storage_provider_config
SET is_active = 0
WHERE is_active = 1;
UPDATE tb_storage_provider_config
SET is_active = 1,
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM tb_storage_provider_config
WHERE provider = #{provider}
